pragma solidity ^0.8.20;

contract Vault {
    mapping(address => uint256) public balanceOf;
    address public owner;

    event Deposited(address indexed user, uint256 amount);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function deposit() external payable {
        balanceOf[msg.sender] += msg.value;
        emit Deposited(msg.sender, msg.value);
    }

    function withdraw(uint256 amount) external {
        require(balanceOf[msg.sender] >= amount, "Insufficient balance");
        balanceOf[msg.sender] -= amount;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "Transfer failed");
    }
}

pragma solidity ^0.8.20;

contract Counter {
    uint256 public count;

    function increment() public {
        count++;
    }

    function getCount() public view returns (uint256) {
        return count;
    }
}

function transfer(address to, uint256 amount) external {
    require(balanceOf[msg.sender] >= amount, "insufficient");
    balanceOf[msg.sender] -= amount;
    balanceOf[to] += amount;
    emit Transfer(msg.sender, to, amount);
}

function mint(uint256 amount) external onlyOwner {
    balanceOf[msg.sender] += amount;
    totalSupply += amount;
}

// UNSAFE: send first, update later — re-entrant call sees the old balance
function withdraw(uint256 amount) external {
    require(balanceOf[msg.sender] >= amount);
    (bool ok, ) = msg.sender.call{value: amount}("");   // callee runs here
    balanceOf[msg.sender] -= amount;                     // too late
    require(ok, "failed");
}

// SAFE: checks → effects → interactions
function withdraw(uint256 amount) external {
    require(balanceOf[msg.sender] >= amount);             // checks
    balanceOf[msg.sender] -= amount;                     // effects
    (bool ok, ) = msg.sender.call{value: amount}("");    // interactions
    require(ok, "failed");
}
